public static int findNthLeapYear(int Y, int N) {
    if (Y < 1 || N < 1) {
        throw new IllegalArgumentException("Invalid input: Y and N must be positive");
    }
    int count = 0;
    for (int year = Y; year <= Integer.MAX_VALUE; year++) {
        if (isLeapYear(year)) {
            count++;
            if (count == N) {
                return year;
            }
        }
    }
    throw new IllegalStateException("Failed to find the " + N + "th leap year after " + Y);
}

private static boolean isLeapYear(int year) {
    if (year % 4 != 0) {
        return false;
    }
    if (year % 100 == 0 && year % 400 != 0) {
        return false;
    }
    return true;
}
```
