canonical_solution:
{
  tree = new ArrayList<>();
  res = new int[n];
  Arrays.fill(res, -1);
  for (int i = 0; i < n; ++i) tree.add(new HashSet<>());
  for (int[] e : edges) {
    tree.get(e[0]).add(e[1]);
    tree.get(e[1]).add(e[0]);
  }
  return dfs(hasApple, 0, -1);
}

int dfs(boolean[] hasApple, int node, int parent) {
  if (res[node] >= 0) return res[node];
  int total = 0;
  for (int child : tree.get(node)) {
    if (child == parent) continue;
    int childCost = dfs(hasApple, child, node);
    if (childCost > 0 || hasApple[child]) total += childCost + 2;
  }
  return res[node] = total;
}

